PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?artist ?artistLabel ?child ?childLabel WHERE {
  <http://dbpedia.org/resource/Me_and_Bobby_McGee> dbo:artist ?artist .
  OPTIONAL { ?artist rdfs:label ?artistLabel . FILTER (lang(?artistLabel) = "en") }
  ?artist dbo:child ?child .
  OPTIONAL { ?child rdfs:label ?childLabel . FILTER (lang(?childLabel) = "en") }
}
LIMIT 100

